Method.Implementation:

if ($get(%session.Data("PsWd")) = "")
{
	&js<alert('Server Method, login required');>
	Quit $$$ERROR($$$EnsErrGeneral, "Please login")		
}

return $$$OK

 Do %page.%SetValueById("namespLbl",$NAMESPACE)
 Do %page.%SetValueById("userLbl",$get(%session.Data("UsNm")))
 Do %page.%SetValueById("systemLbl", $SYSTEM)
 set button = %page.%GetComponentById("changeFunc")
 if $ISOBJECT(button)
 {
	 set button.caption = "Src Control"
 }
  try {
	Set img = %page.%GetComponentById("TemplateLogo")
    Set stream=##class(%FileBinaryStream).%New()

    if $$$ISOK(stream.LinkToFile("/WORK/common/images/intermountain.jpg"))
    {
     Set oid=stream.%Oid()
     Set img.streamId = oid 
   }
 } catch err
 {
 }
 return $$$OK

	zenPage.getComponentById('lblAccess').setValue('Creating file');
   var comp = zenPage.getComponentById('Component').getValue();
   var nmSp = zenPage.getComponentById('Namespace').getValue();
    if(comp != '' && nmSp != '')
    {
	   try
	    {		    
   			var statStr = zenPage.CreateDeploymentFiles(comp, nmSp);

	   		zenPage.getComponentById('lblAccess').setValue(statStr);

	    } catch(err)
	    {
		    zenPage.getComponentById('lblAccess').setValue('Exception: ' + err.message);
	    }
    }


   var comp = zenPage.getComponentById('Component').getValue();

    if(comp != '')
    {
	   try
	    {		    
   			var statStr = zenPage.FindDeploymentFiles(comp);

	   		zenPage.getComponentById('lblAccess').setValue(statStr);

	    } catch(err)
	    {
		    zenPage.getComponentById('lblAccess').setValue('Exception: ' + err.message);
	    }
    }

var deployType = zenPage.getComponentById('comboboxdeployType').getValue();
grp = zenPage.getComponentById('redeployGrp');
if (deployType == 'update')
{
	grp.setProperty('hidden', false);
}
else
{
	grp.setProperty('hidden', true);
}

	zenPage.getComponentById('lblAccess').setValue('Deploying');
   var comp = zenPage.getComponentById('deployComponent').getValue();
   var nmSp = zenPage.getComponentById('deployNamespace').getValue();
   var rev = zenPage.getComponentById('deployRev').getValue();
   var depCls = zenPage.getComponentById('DeployClasses').getValue();
   var depConf = zenPage.getComponentById('DeployConfig').getValue();

   var deployType = zenPage.getComponentById('comboboxdeployType').getValue();


    if(comp == '' || nmSp == '' || rev == '' || deployType == '' || (deployType == 'update' && depConf == '' && depCls == '') ) 
    {
	  zenPage.getComponentById('lblAccess').setValue('Error');
	   var group = this.createComponent('modalGroup'); 
      group.setProperty('height', 100);
      zenPage.addChild(group);

      var lbl = this.createComponent('label'); 
      group.addChild(lbl); 

      lbl.setProperty('value','Missing required field');
      // lbl.setProperty('height', 50)

      var sp1 = this.createComponent('spacer'); 
      sp1.setProperty('height', 10);
      group.addChild(sp1);

      var hg = this.createComponent('hgroup'); 
      group.addChild(hg); 
      hg.setProperty('cellAlign', 'center')

      var btn = this.createComponent('button'); 
      hg.addChild(btn); 
      btn.setProperty('caption','OK'); 
      btn.setProperty('onclick','zenPage.btnCancel();'); 
      btn.setProperty('align', 'center');

       var sp = this.createComponent('spacer'); 
      hg.addChild(sp); 
      sp.setProperty('width', 50);

      zenPage.refreshContents(true); 

      group.show('Error', 'dynamic'); 
    } 
    else { 
	  var group = this.createComponent('modalGroup'); 
      group.setProperty('height', 100);
      zenPage.addChild(group);

      var lbl = this.createComponent('label'); 
      group.addChild(lbl); 

      lbl.setProperty('value','You want Deploy <B>' + comp + '</B> to ' + zenPage.getComponentById('systemLbl').getValue());
      // lbl.setProperty('height', 50)

      var sp1 = this.createComponent('spacer'); 
      sp1.setProperty('height', 10);
      group.addChild(sp1);

      var hg = this.createComponent('hgroup'); 
      group.addChild(hg); 
      hg.setProperty('cellAlign', 'center')

      var btn = this.createComponent('button'); 
      hg.addChild(btn); 
      btn.setProperty('caption','Cancel'); 
      btn.setProperty('onclick','zenPage.btnCancel();'); 

       var sp = this.createComponent('spacer'); 
      hg.addChild(sp); 
      sp.setProperty('width', 50);

       var btn2 = this.createComponent('button'); 
      hg.addChild(btn2); 
      btn2.setProperty('caption','OK'); 
      btn2.setProperty('onclick','zenPage.btnOk();'); 

      zenPage.refreshContents(true); 

      group.show('Deploy', 'dynamic');

   }

   var comp = zenPage.getComponentById('deployComponent').getValue();
   var nmSp = zenPage.getComponentById('deployNamespace').getValue();
   var rev = zenPage.getComponentById('deployRev').getValue();
   var deployType = zenPage.getComponentById('comboboxdeployType').getValue();
    var depCls = zenPage.getComponentById('DeployClasses').getValue();
   var depConf = zenPage.getComponentById('DeployConfig').getValue();

    zenPage.endModal();
	    try
	    {	

	    	var statStr = zenPage.VerifyRevNum(comp, rev )
	    	if( statStr.length > 0)
	    	{
		    	if( statStr.search("Fatal Error") > 0)
		    	{
			    	zenPage.getComponentById('lblAccess').setValue(statStr);
			    	return;
		    	}
		    	zenPage.VerifyWithUser(statStr, comp, nmSp, deployType, rev, depCls, depConf);
	    	}
	    	else
	    	{
   				var statStr = zenPage.CallDeployService(comp, nmSp, deployType, rev, depCls, depConf);

	   			zenPage.getComponentById('lblAccess').setValue(statStr);
	    	}

	    } catch(err)
	    {
		    zenPage.getComponentById('lblAccess').setValue('Exception: ' + err.message);
	    }

	zenPage.getComponentById('lblAccess').setValue('Verifying');
   var comp = zenPage.getComponentById('verComponent').getValue();
   var nmSp = zenPage.getComponentById('verNamespace').getValue();

    if(comp != '' && nmSp != '')
    {
	   try
	    {
	   zenSynchronousMode = false;
	  var group = this.createComponent('modalGroup'); 
      group.setProperty('height', 100);
      zenPage.addChild(group);

      var lbl = this.createComponent('label'); 
      group.addChild(lbl); 
      lbl.setProperty('value','Please Wait, Verifying: ' + comp)
		zenPage.refreshContents(true); 
    	group.show('Verify', 'dynamic');

     	zenPage.getComponentById('lblAccess').setProperty('hidden', false);
     	timerVar = setInterval(function(){ zenPage.VerifyTimer()}, 1000);

   		zenPage.CallVerifyService(comp, nmSp);


	    } catch(err)
	    {
		    zenPage.getComponentById('lblAccess').setValue('Exception: ' + err.message);
		    clearInterval(this);
		    zenSynchronousMode = true;
	    }

    }

   try
	    {
		    if( zenPage.getComponentById('lblAccess').getValue().substr(0, 9)  != 'Verifying')
  			{
	  			clearInterval(timerVar);  
	  			if (zenPage.modalStack != null && zenPage.modalStack.length>0)
	  			{
	  				zenPage.endModal();		
	  			}		
   				zenSynchronousMode = true;   			  				 
  			}
  			else
  			{
	  			zenPage.getComponentById('lblAccess').setValue(zenPage.getComponentById('lblAccess').getValue() + ".");
  			}


} catch(err)
	    {
		    zenPage.getComponentById('lblAccess').setValue('Exception in VerifyTimer: ' + err.message);
		    clearInterval(timerVar);
		    zenSynchronousMode = true;
	    }

	zenPage.getComponentById('lblAccess').setValue('Verify: ' + msg);


	  var group = this.createComponent('modalGroup'); 
      group.setProperty('height', 100);
      zenPage.addChild(group);

      var lbl = this.createComponent('label'); 
      group.addChild(lbl); 
      lbl.setProperty('value', msg + "<BR> Do you want to continue with deploying the version #: " + rev + " which is not the last checked in version?");

      var sp1 = this.createComponent('spacer'); 
      sp1.setProperty('height', 10);
      group.addChild(sp1);

      var hg = this.createComponent('hgroup'); 
      group.addChild(hg); 
      hg.setProperty('cellAlign', 'center')

      var btn = this.createComponent('button'); 
      hg.addChild(btn); 
      btn.setProperty('caption','Cancel'); 
      btn.setProperty('onclick','zenPage.btnCancel();'); 

       var sp = this.createComponent('spacer'); 
      hg.addChild(sp); 
      sp.setProperty('width', 50);

       var btn2 = this.createComponent('button'); 
      hg.addChild(btn2); 
      btn2.setProperty('caption','OK'); 
      btn2.setProperty('onclick','zenPage.btnContinue();'); 

      zenPage.refreshContents(true); 

      group.show('Warning', 'dynamic');

   var comp = zenPage.getComponentById('deployComponent').getValue();
   var nmSp = zenPage.getComponentById('deployNamespace').getValue();
   var rev = zenPage.getComponentById('deployRev').getValue();
   var deployType = zenPage.getComponentById('comboboxdeployType').getValue();
    var depCls = zenPage.getComponentById('DeployClasses').getValue();
   var depConf = zenPage.getComponentById('DeployConfig').getValue();

    zenPage.endModal();
	    try
	    {		    

   			var statStr = zenPage.CallDeployService(comp, nmSp, deployType, rev, depCls, depConf);

	   		zenPage.getComponentById('lblAccess').setValue(statStr);

	    } catch(err)
	    {
		    zenPage.getComponentById('lblAccess').setValue('Exception: ' + err.message);
	    }


set retStr = ""
try {

set createDeployCls = ##class(IHC.ITF.SrcCtrlPkg.CreateDeploymentFiles).%New()
set retStr = createDeployCls.CreateDeploymentFiles(comp, nmSp, $get(%session.Data("UsNm")), $get(%session.Data("PsWd")) )

} catch(err)
{
	set retStr = "Could not create Deployment files " _ err.Data
}

Return retStr


set retStr = ""
try {

set createDeployCls = ##class(IHC.ITF.SrcCtrlPkg.CreateDeploymentFiles).%New()
set comp = $ZSTRIP(comp,"<>WC")
// Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), "GetVersions:" _ comp _ "$")
set retStr = createDeployCls.GetVersions(comp, $get(%session.Data("UsNm")), $get(%session.Data("PsWd")), 1 )
if ($L(retStr) <= 0)
{
	set retStr = "Could not find Deployment files for " _ comp
}
if ( $FIND(retStr, "Last Changed Rev") > 0)
{
	set retStr = $REPLACE(retStr, "Last Changed Rev", "<B>Last Changed Rev</B>", 0, 1, 1)
}
} catch(err)
{
	set retStr = "Could not find Deployment files " _ err.Data
}

Return retStr


set retStr = ""

try {
	set deployCls = ##class(IHC.ITF.SrcCtrlPkg.DeployFilesToNamespace).%New()
	set stat = deployCls.ValidateSvnRevision(comp, $get(%session.Data("UsNm")), $get(%session.Data("PsWd")), revNum )
	if $$$ISERR(stat)
	{
		 if $GET(%objlasterror) '= ""
    	{
        	set retStr =  $System.Status.GetErrorText(%objlasterror)
    	}
    	else
    	{
			set retStr = "Fail: " _ tSC
    	}
	}

} catch(err)
{
	set retStr = "Exception: Could not find files from SVN " _ err.Data
}
// Remove unprintable chars

return $ZSTRIP(retStr, "*C")


set retStr = ""
set sysEnv = $ZCVT($SYSTEM, "U")
if ( $FIND(sysEnv, "PRD") > 0)
{
	set env = "PROD"
}
elseif ( $FIND(sysEnv, "UAT") > 0)
{
	set env = "UAT"
}
elseif ( $FIND(sysEnv, "QA") > 0)
{
	set env = "QA"
}
else
{
	set env = "DEV"
}
try {
	set comp = $ZSTRIP(comp,"<>WC")
	set deployCls = ##class(IHC.ITF.SrcCtrlPkg.DeployFilesToNamespace).%New()
	set retStr = deployCls.DeployFiles(comp, deployType , nmSp , $get(%session.Data("UsNm")), $get(%session.Data("PsWd")), revNum, env, depCls,  depConf )

} catch(err)
{
	set retStr = "Exception: Could not deploy files " _ err.Data
}
return retStr


set retStr = ""
set sysEnv = $ZCVT($SYSTEM, "U")
if ( $FIND(sysEnv, "PRD") > 0)
{
	set env = "PROD"
}
elseif ( $FIND(sysEnv, "UAT") > 0)
{
	set env = "UAT"
}
elseif ( $FIND(sysEnv, "QA") > 0)
{
	set env = "QA"
}
else
{
	set env = "DEV"
}
set errStr = "OK"
try {
	set retStr = "" 
	set vCls = ##class(IHC.ITF.SrcCtrlPkg.VerifyClasses).%New()
	set comp = $ZSTRIP(comp,"<>WC")
	set stat = vCls.VerifyClassFiles(comp, nmSp , $get(%session.Data("UsNm")), $get(%session.Data("PsWd")), env, .retStr)
	if $$$ISOK(stat)
	{
		set retStr = "<B>Verification Passed</B>;; " _ retStr
		set retStr = $Replace(retStr, ";", "<br/>")
	}
	else
	{

	set retStr = "<B>Failed</B>; Details: " _ %objlasterror _ "; " _retStr
	}


} catch(err)
{
	set retStr = "Exception: Could not verify files " _ err.Data
}
Do ..%SetValueById("lblAccess", retStr)
Quit
